```go
// main.go
package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"

	"github.com/gin-gonic/gin"
	_ "github.com/lib/pq"
)

var db *sql.DB

func main() {
	var err error
	db, err = sql.Open("postgres", os.Getenv("DATABASE_URL"))
	if err != nil {
		log.Fatal(err)
	}

	r := gin.Default()
	r.GET("/users", getUsers)
	r.POST("/exec", runCommand)
	r.GET("/fetch", fetchURL)
	r.Run(":8080")
}

func getUsers(c *gin.Context) {
	name := c.Query("name")
	rows, err := db.Query(fmt.Sprintf("SELECT id, name, email FROM users WHERE name = '%s'", name))
	if err != nil {
		c.JSON(500, err.Error())
		return
	}
	defer rows.Close()
	var users []map[string]interface{}
	for rows.Next() {
		var id int
		var userName, email string
		rows.Scan(&id, &userName, &email)
		users = append(users, map[string]interface{}{"id": id, "name": userName, "email": email})
	}
	c.JSON(200, users)
}

func runCommand(c *gin.Context) {
	var req struct {
		Cmd string `json:"cmd"`
	}
	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(400, gin.H{"error": err.Error()})
		return
	}
	out, err := exec.Command("sh", "-c", req.Cmd).CombinedOutput()
	if err != nil {
		c.JSON(500, string(out))
		return
	}
	c.JSON(200, gin.H{"output": string(out)})
}

func fetchURL(c *gin.Context) {
	targetURL := c.Query("url")
	resp, err := http.Get(targetURL)
	if err != nil {
		c.JSON(500, gin.H{"error": err.Error()})
		return
	}
	defer resp.Body.Close()
	body, _ := io.ReadAll(resp.Body)
	c.Data(200, "text/plain", body)
}
